    aIngress = 0xAB4E9C9C36BBC971ULL;
    aCarry = 0xC4B320C4BB32B856ULL;
    aWandererA = 0xE332E0487E197A18ULL;
    aWandererB = 0xCF64C47ACBBD7D77ULL;
    aWandererC = 0xE4EC8D902553FF31ULL;
