    KDF_D(pWorkSpace, pNonce, &(mDomainBundleEphemeral.mSeedConstants), &(mDomainBundleEphemeral.mSeedSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mSeedSalts,
                    &(pWorkSpace->mDomainBundle.mSeedConstants));
    //
    //
    ////////////////////////////////////////////////////////
    //
    // Seed stages
    //
    aIngress = 0xA393F10F3C259AD8ULL;
    aCarry = 0xE025C1CF54DF7509ULL;
    aWandererA = 0xFC8C1B43513E2F93ULL;
    aWandererB = 0xEDBFF93CC1D92B95ULL;
    aWandererC = 0x9FF679134A6B0124ULL;
    aWandererD = 0xF6ADDA18FACCFFA6ULL;
    aWandererE = 0x99F6F47373BCC081ULL;
    aWandererF = 0xAF6FBEF10C5BA343ULL;
    aWandererG = 0xD56D44BDE7A46E6AULL;
    aWandererH = 0x96D1279CC7FA23CDULL;
    aWandererI = 0xD6300958AA2AD69CULL;
    aWandererJ = 0xC8A4211A8F7D0FC0ULL;
    aWandererK = 0xF10E2A6E40DC81CAULL;

    //
    TwistExpander_Alioth_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Alioth_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Alioth_Arx::SEED_C(PARAMS_SEED);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;
